package com.retrospect;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;

/** Turns buffered frames into a video file. */
final class ClipWriter
{
	private ClipWriter()
	{
	}

	/**
	 * Picks one frame per output slot so the clip plays at real speed even if some
	 * captures were late or dropped.
	 */
	static List<FrameBuffer.Frame> resample(List<FrameBuffer.Frame> frames, int fps)
	{
		List<FrameBuffer.Frame> out = new ArrayList<>();
		if (frames.isEmpty())
		{
			return out;
		}
		long start = frames.get(0).timeMs;
		long end = frames.get(frames.size() - 1).timeMs;
		int slots = (int) Math.max(1, Math.round((end - start) * fps / 1000.0) + 1);
		int i = 0;
		for (int s = 0; s < slots; s++)
		{
			long want = start + Math.round(s * 1000.0 / fps);
			while (i + 1 < frames.size()
				&& Math.abs(frames.get(i + 1).timeMs - want) <= Math.abs(frames.get(i).timeMs - want))
			{
				i++;
			}
			out.add(frames.get(i));
		}
		return out;
	}

	/** A resized game window mid-clip would break the video, so keep only the most recent size. */
	private static List<FrameBuffer.Frame> sameSize(List<FrameBuffer.Frame> frames)
	{
		if (frames.isEmpty())
		{
			return frames;
		}
		FrameBuffer.Frame ref = frames.get(frames.size() - 1);
		List<FrameBuffer.Frame> out = new ArrayList<>();
		for (FrameBuffer.Frame f : frames)
		{
			if (f.width == ref.width && f.height == ref.height)
			{
				out.add(f);
			}
		}
		return out;
	}

	/**
	 * AVI (Motion JPEG). Needs nothing installed and saves instantly because the frames
	 * are stored as they are. Plays in VLC and most desktop players.
	 */
	static void writeAvi(List<FrameBuffer.Frame> frames, int fps, Filepath file) throws IOException
	{
		List<FrameBuffer.Frame> seq = sameSize(resample(frames, fps));
		if (seq.isEmpty())
		{
			throw new IOException("no frames to save");
		}
		int w = seq.get(0).width;
		int h = seq.get(0).height;
		int n = seq.size();
		int maxFrame = 0;
		for (FrameBuffer.Frame f : seq)
		{
			maxFrame = Math.max(maxFrame, f.jpeg.length);
		}
		try (Out out = new Out(file.openFileChannel(
			StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING)))
		{
			out.tag("RIFF");
			long riffSize = out.pos();
			out.le32(0);
			out.tag("AVI ");

			out.tag("LIST");
			long hdrlSize = out.pos();
			out.le32(0);
			out.tag("hdrl");

			out.tag("avih");
			out.le32(56);
			out.le32(1_000_000 / fps); // microseconds per frame
			out.le32(maxFrame * fps);  // peak bytes per second
			out.le32(0);
			out.le32(0x10);            // file has an index
			out.le32(n);
			out.le32(0);
			out.le32(1);               // one stream
			out.le32(maxFrame);
			out.le32(w);
			out.le32(h);
			out.le32(0);
			out.le32(0);
			out.le32(0);
			out.le32(0);

			out.tag("LIST");
			long strlSize = out.pos();
			out.le32(0);
			out.tag("strl");

			out.tag("strh");
			out.le32(56);
			out.tag("vids");
			out.tag("MJPG");
			out.le32(0);
			out.le32(0);
			out.le32(0);
			out.le32(1);   // scale
			out.le32(fps); // rate
			out.le32(0);
			out.le32(n);
			out.le32(maxFrame);
			out.le32(-1);
			out.le32(0);
			out.le16(0);
			out.le16(0);
			out.le16(w);
			out.le16(h);

			out.tag("strf");
			out.le32(40);
			out.le32(40);
			out.le32(w);
			out.le32(h);
			out.le16(1);
			out.le16(24);
			out.tag("MJPG");
			out.le32(w * h * 3);
			out.le32(0);
			out.le32(0);
			out.le32(0);
			out.le32(0);

			out.patch(strlSize);
			out.patch(hdrlSize);

			out.tag("LIST");
			long moviSize = out.pos();
			out.le32(0);
			long moviStart = out.pos();
			out.tag("movi");
			int[] offsets = new int[n];
			int[] sizes = new int[n];
			for (int i = 0; i < n; i++)
			{
				byte[] jpeg = seq.get(i).jpeg;
				offsets[i] = (int) (out.pos() - moviStart);
				sizes[i] = jpeg.length;
				out.tag("00dc");
				out.le32(jpeg.length);
				out.bytes(jpeg);
				if ((jpeg.length & 1) == 1)
				{
					out.u8(0);
				}
			}
			out.patch(moviSize);

			out.tag("idx1");
			out.le32(n * 16);
			for (int i = 0; i < n; i++)
			{
				out.tag("00dc");
				out.le32(0x10); // every frame is a key frame
				out.le32(offsets[i]);
				out.le32(sizes[i]);
			}
			out.patch(riffSize);
		}
	}

	/**
	 * A little buffered writer over the channel Filepath hands us. Plugins are not allowed to
	 * reach for java.io, so this replaces what RandomAccessFile used to do: append little-endian
	 * values, and go back afterwards to fill in a chunk size once its length is known.
	 */
	private static final class Out implements AutoCloseable
	{
		private final FileChannel ch;
		private final ByteBuffer buf = ByteBuffer.allocate(1 << 16).order(ByteOrder.LITTLE_ENDIAN);
		private long flushed;

		Out(FileChannel ch)
		{
			this.ch = ch;
		}

		/** Where the next byte will land, counting what is still sitting in the buffer. */
		long pos()
		{
			return flushed + buf.position();
		}

		private void room(int bytes) throws IOException
		{
			if (buf.remaining() < bytes)
			{
				flush();
			}
		}

		private void flush() throws IOException
		{
			buf.flip();
			while (buf.hasRemaining())
			{
				flushed += ch.write(buf);
			}
			buf.clear();
		}

		void tag(String fourcc) throws IOException
		{
			bytes(fourcc.getBytes(StandardCharsets.US_ASCII));
		}

		void le32(int v) throws IOException
		{
			room(4);
			buf.putInt(v);
		}

		void le16(int v) throws IOException
		{
			room(2);
			buf.putShort((short) v);
		}

		void u8(int v) throws IOException
		{
			room(1);
			buf.put((byte) v);
		}

		void bytes(byte[] b) throws IOException
		{
			if (b.length > buf.capacity())
			{
				flush();
				ByteBuffer direct = ByteBuffer.wrap(b);
				while (direct.hasRemaining())
				{
					flushed += ch.write(direct);
				}
				return;
			}
			room(b.length);
			buf.put(b);
		}

		/** Fills in the 4-byte size field at sizeField with the length of the chunk it opens. */
		void patch(long sizeField) throws IOException
		{
			long end = pos();
			flush();
			ByteBuffer size = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
			size.putInt((int) (end - sizeField - 4));
			size.flip();
			long at = sizeField;
			while (size.hasRemaining())
			{
				at += ch.write(size, at);
			}
		}

		@Override
		public void close() throws IOException
		{
			try
			{
				flush();
			}
			finally
			{
				ch.close();
			}
		}
	}

	/**
	 * Keeps the clips folder under the storage limit by removing the oldest clips first.
	 * Only ever touches .avi and .mp4 files inside the Retrospect clips folder, and never the newest clip.
	 */
	static void enforceCap(Filepath clipsDir, long capBytes, Filepath keep) throws IOException
	{
		if (!clipsDir.isDirectory())
		{
			return;
		}
		List<Filepath> found;
		try (Stream<Filepath> walk = clipsDir.walk(2))
		{
			found = walk.filter(Filepath::isFile)
				.filter(f -> f.getFileName().endsWith(".avi") || f.getFileName().endsWith(".mp4"))
				.collect(Collectors.toCollection(ArrayList::new));
		}
		// Size and timestamp both throw, so they are read in a plain loop rather than a comparator.
		List<Clip> clips = new ArrayList<>(found.size());
		long total = 0;
		for (Filepath f : found)
		{
			try
			{
				Clip c = new Clip(f, f.size(), f.getLastModifiedTime().toMillis());
				clips.add(c);
				total += c.bytes;
			}
			catch (IOException e)
			{
				// Vanished or unreadable: leave it out of the accounting rather than fail the save.
			}
		}
		clips.sort(Comparator.comparingLong(c -> c.modified));
		for (Clip c : clips)
		{
			if (total <= capBytes)
			{
				break;
			}
			if (keep != null && c.path.equals(keep))
			{
				continue;
			}
			try
			{
				c.path.delete();
				total -= c.bytes;
			}
			catch (IOException e)
			{
				// In use or already gone: skip it and try the next oldest.
			}
		}
	}

	private static final class Clip
	{
		private final Filepath path;
		private final long bytes;
		private final long modified;

		Clip(Filepath path, long bytes, long modified)
		{
			this.path = path;
			this.bytes = bytes;
			this.modified = modified;
		}
	}

	/** Turns "Drop: Vorkath (1.2m)" into something safe for a file name. */
	static String safeName(String label)
	{
		String s = label == null ? "" : label.toLowerCase().replaceAll("[^a-z0-9]+", "-").replaceAll("^-+|-+$", "");
		if (s.length() > 40)
		{
			s = s.substring(0, 40).replaceAll("-+$", "");
		}
		return s.isEmpty() ? "moment" : s;
	}
}

package com.retrospect;

import java.util.ArrayList;
import java.util.List;

/** The readable result of one fight: one takeaway first, the detail underneath. */
final class Debrief
{
	String title;
	/** A short line of OSRS banter for the situation, or null. */
	String vibe;
	/** "Fought: A, B" for player fights, or null. */
	String fought;
	String takeaway;
	/** One concrete thing to try next time, tied to the takeaway. May be null. */
	String tip;
	final List<String> strong = new ArrayList<>();
	final List<String> weak = new ArrayList<>();
	final List<String> stats = new ArrayList<>();
	/** Two columns: your moments on the left, theirs on the right. */
	final List<String> timeline = new ArrayList<>();
	String clip;

	String toText()
	{
		StringBuilder sb = new StringBuilder();
		String nl = System.lineSeparator();
		sb.append(title);
		if (vibe != null)
		{
			sb.append("  ").append(vibe);
		}
		sb.append(nl);
		if (fought != null)
		{
			sb.append(fought).append(nl);
		}
		sb.append(nl).append("THE TAKEAWAY").append(nl).append(takeaway).append(nl);
		if (tip != null)
		{
			sb.append(nl).append("TRY THIS").append(nl).append(tip).append(nl);
		}
		section(sb, "STRONG", strong, nl);
		section(sb, "WEAK", weak, nl);
		section(sb, "NUMBERS", stats, nl);
		sb.append(nl).append("WHAT HAPPENED").append(nl);
		for (String s : timeline)
		{
			sb.append(s).append(nl);
		}
		if (clip != null)
		{
			sb.append(nl).append("Clip: ").append(clip).append(nl);
		}
		return sb.toString();
	}

	private static void section(StringBuilder sb, String name, List<String> lines, String nl)
	{
		if (lines.isEmpty())
		{
			return;
		}
		sb.append(nl).append(name).append(nl);
		for (String s : lines)
		{
			sb.append("- ").append(s).append(nl);
		}
	}
}

package com.retrospect;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * Reads a finished fight and says the one thing worth knowing first, what was strong,
 * what was weak, and one thing to try next time.
 * Pure logic: no game objects, so every rule here is covered by tests.
 */
final class DebriefBuilder
{
	static final int MAX_TIMELINE_LINES = 28;
	private static final int LEFT_WIDTH = 10;

	/** Special attacks recognisable by their animation, so player fights read properly out of the box. */
	static final Map<String, String> KNOWN_MOVES = new HashMap<>();

	static
	{
		KNOWN_MOVES.put("1062", "dds spec");
		KNOWN_MOVES.put("1378", "dwh spec");
		KNOWN_MOVES.put("1667", "g maul spec");
		KNOWN_MOVES.put("7514", "claw spec");
		KNOWN_MOVES.put("7515", "d sword spec");
		KNOWN_MOVES.put("7638", "zgs spec");
		KNOWN_MOVES.put("7639", "zgs spec");
		KNOWN_MOVES.put("7640", "sgs spec");
		KNOWN_MOVES.put("7642", "bgs spec");
		KNOWN_MOVES.put("7644", "ags spec");
		KNOWN_MOVES.put("7645", "ags spec");
		KNOWN_MOVES.put("10427", "ags spec");
		KNOWN_MOVES.put("9171", "ancient gs spec");
		KNOWN_MOVES.put("11124", "elder maul spec");
		KNOWN_MOVES.put("11140", "burning claws spec");
		KNOWN_MOVES.put("11240", "voidwaker spec");
		KNOWN_MOVES.put("11275", "voidwaker spec");
	}

	/** A weak point and, where there is one, the thing to try about it. */
	private static final class Point
	{
		final String text;
		final String tip;

		Point(String text, String tip)
		{
			this.text = text;
			this.tip = tip;
		}
	}

	private DebriefBuilder()
	{
	}

	static Debrief build(Encounter e, List<FightSummary> past, Function<String, String> moveNames)
	{
		return build(e, past, moveNames, true);
	}

	/**
	 * @param past      earlier fights against the same target (not including this one)
	 * @param moveNames turns a move key such as "14322" into a nickname, or returns null
	 * @param lingo     add a short line of OSRS banter where one fits
	 */
	static Debrief build(Encounter e, List<FightSummary> past, Function<String, String> moveNames, boolean lingo)
	{
		Debrief d = new Debrief();
		String length = clock(e.durationTicks());
		switch (e.outcome)
		{
			case KILL:
				d.title = e.target + ": kill in " + length + (e.lootValue > 0 ? " (+" + gp(e.lootValue) + ")" : "");
				break;
			case DEATH:
				d.title = e.target + ": you died after " + length;
				break;
			default:
				d.title = e.target + ": fight ended after " + length + " (no kill)";
		}
		if (!e.opponents.isEmpty())
		{
			d.fought = "Fought: " + String.join(", ", e.opponents);
		}

		List<FightSummary> kills = new ArrayList<>();
		for (FightSummary s : past)
		{
			if (s.isKill())
			{
				kills.add(s);
			}
		}
		boolean record = isRecord(e, kills);

		// ---------- weak ----------
		List<Point> weak = new ArrayList<>();
		if (e.outcome == Encounter.Outcome.DEATH)
		{
			weak.add(death(e, moveNames));
		}
		Point source = source(e, moveNames);
		Point idle = idle(e);
		boolean tookALot = e.maxHp > 0 ? e.taken >= e.maxHp : e.taken >= 99;
		if (source != null && tookALot)
		{
			weak.add(source);
			addIf(weak, idle);
		}
		else
		{
			addIf(weak, idle);
			addIf(weak, source);
		}
		addIf(weak, rhythm(e));
		addIf(weak, accuracyDrop(e, past));
		if (e.outcome != Encounter.Outcome.DEATH && e.lowDips >= 2)
		{
			weak.add(new Point("You dropped under a quarter health " + e.lowDips + " times and got away with it.",
				"Eat when you fall under " + e.eatFloor() + " HP. The biggest hit here was " + e.maxTaken + ", so anything lower is a coin flip."));
		}
		if (e.earlyEats >= 3)
		{
			weak.add(new Point("You healed " + e.earlyEats + " times while already above 80% health.",
				"Hold your food until you are under " + e.eatFloor() + " HP. Every early bite costs you an attack."));
		}

		// ---------- strong ----------
		List<String> strong = new ArrayList<>();
		if (record)
		{
			strong.add("Fastest kill you have on record: " + length + " (previous best " + clock(best(kills)) + ").");
		}
		if (e.outcome == Encounter.Outcome.KILL && e.taken == 0 && e.hits > 0)
		{
			strong.add("No damage taken. Flawless.");
		}
		if (e.outcome == Encounter.Outcome.KILL && e.targetIsPlayer && e.lootValue > 0)
		{
			strong.add("Killed " + e.target + " for " + gp(e.lootValue) + ".");
		}
		int attacks = e.attackTicks.size();
		int missed = e.missedAttacks();
		if (e.expectedSpeed() > 0 && attacks >= 10 && missed * 100 / (attacks + missed) <= 5)
		{
			strong.add("You stayed on the target: almost no idle time across " + attacks + " attacks.");
		}
		int specHit = bestSpecHit(e);
		if (specHit > 0)
		{
			strong.add("Your special attack landed for " + specHit + ".");
		}
		if (e.maxHp > 0 && e.taken * 2 >= e.maxHp && e.lowestHp * 5 > e.maxHp * 2)
		{
			strong.add("You took " + e.taken + " damage and never fell under " + e.lowestHp + " HP. Your healing was on time.");
		}
		addIf(strong, accuracyUp(e, past));
		addIf(strong, lessDamage(e, kills));

		// ---------- the takeaway ----------
		if (!weak.isEmpty())
		{
			Point first = weak.remove(0);
			d.takeaway = first.text;
			d.tip = first.tip;
		}
		else if (!strong.isEmpty())
		{
			d.takeaway = strong.remove(0);
		}
		else
		{
			d.takeaway = e.outcome == Encounter.Outcome.KILL
				? "Clean fight. Nothing stands out to fix."
				: "Not enough happened in this fight to say anything useful.";
		}
		for (Point p : weak)
		{
			if (d.weak.size() < 3)
			{
				d.weak.add(p.tip == null ? p.text : p.text + " Try: " + p.tip);
			}
		}
		for (String s : strong)
		{
			if (d.strong.size() < 3)
			{
				d.strong.add(s);
			}
		}
		if (lingo)
		{
			d.vibe = vibe(e, record);
		}

		stats(e, d, kills);
		timeline(e, d, moveNames);
		return d;
	}

	private static <T> void addIf(List<T> list, T item)
	{
		if (item != null)
		{
			list.add(item);
		}
	}

	// ---------- weak points ----------

	private static Point death(Encounter e, Function<String, String> moveNames)
	{
		StringBuilder sb = new StringBuilder("You died ").append(clock(e.durationTicks())).append(" in");
		if (e.targetHpPct >= 0)
		{
			sb.append(" with ").append(e.target).append(" at ").append(e.targetHpPct).append("% health");
		}
		sb.append(".");

		// What the last few seconds looked like
		int window = 10;
		Map<String, Integer> byMove = new LinkedHashMap<>();
		int lost = 0;
		for (Encounter.Event ev : e.events)
		{
			if (ev.kind == Encounter.Kind.TOOK && ev.tick >= e.endTick - window)
			{
				lost += ev.amount;
				byMove.merge(ev.note, ev.amount, Integer::sum);
			}
		}
		if (lost > 0)
		{
			sb.append(" The last ").append(window * 6 / 10).append(" seconds cost you ").append(lost).append(" HP");
			if (byMove.size() == 1)
			{
				sb.append(", all ").append(during(byMove.keySet().iterator().next(), moveNames));
			}
			else if (byMove.size() <= 3)
			{
				List<String> parts = new ArrayList<>();
				for (Map.Entry<String, Integer> en : byMove.entrySet())
				{
					parts.add(en.getValue() + " " + during(en.getKey(), moveNames));
				}
				sb.append(": ").append(String.join(", ", parts));
			}
			sb.append(".");
		}
		String tip = "Eat when you fall under " + e.eatFloor() + " HP. The biggest hit here was " + e.maxTaken
			+ ", so anything lower is a coin flip.";
		if (e.heals == 0)
		{
			sb.append(" You did not heal at all.");
		}
		else
		{
			int gap = (int) Math.round((e.endTick - e.lastHealTick) * 0.6);
			if (gap >= 5)
			{
				sb.append(" Your last heal was ").append(gap).append(" seconds before that.");
			}
		}
		return new Point(sb.toString(), e.maxTaken > 0 ? tip : null);
	}

	/** One move doing a large share of the damage. */
	private static Point source(Encounter e, Function<String, String> moveNames)
	{
		String worst = e.worstMove();
		if (worst == null || e.taken <= 0)
		{
			return null;
		}
		int[] agg = e.takenByMove.get(worst);
		int share = (int) Math.round(100.0 * agg[1] / e.taken);
		int floor = e.maxHp > 0 ? Math.max(20, e.maxHp * 3 / 10) : 30;
		if (share < 40 || agg[1] < floor || "other".equals(worst))
		{
			return null;
		}
		// Point at the single worst moment so there is something specific to rewatch
		int at = -1;
		int biggest = 0;
		for (Encounter.Event ev : e.events)
		{
			if (ev.kind == Encounter.Kind.TOOK && worst.equals(ev.note) && ev.amount > biggest)
			{
				biggest = ev.amount;
				at = ev.tick;
			}
		}
		String label = moveLabel(worst, moveNames);
		if (e.targetIsPlayer)
		{
			return new Point(agg[1] + " of the " + e.taken + " damage you took (" + share + "%) came from " + label
				+ ", in " + agg[0] + (agg[0] == 1 ? " hit" : " hits") + ".",
				"Eat up before they can do it again: the biggest of those was " + biggest + ".");
		}
		String rewatch = "Rewatch " + clock(at - e.startTick) + ", where " + label + " hit you for " + biggest
			+ ", and find what it does right before it lands.";
		if (namedMove(worst, moveNames) == null && !"other".equals(worst) && !worst.startsWith("@"))
		{
			rewatch += " Call it something in Move nicknames (" + worst + "=your name) and it will show up by name next time.";
		}
		return new Point(agg[1] + " of the " + e.taken + " damage you took (" + share + "%) landed " + during(worst, moveNames)
			+ ", in " + agg[0] + (agg[0] == 1 ? " hit" : " hits") + ". That is the first thing to fix.", rewatch);
	}

	/**
	 * Being a little late on every attack. Idle time only notices whole attacks lost in
	 * one lump; a tick dropped every swing never shows up there, but over a fight it is
	 * the same damage. Only possible because the weapon's real speed is known.
	 */
	private static Point rhythm(Encounter e)
	{
		int weapon = e.weaponSpeed();
		int attacks = e.attackTicks.size();
		if (weapon <= 0 || attacks < 5)
		{
			return null;
		}
		double gap = e.averageGap();
		double late = gap - weapon;
		if (late < 0.5)
		{
			return null;
		}
		int percent = (int) Math.round(late / weapon * 100);
		double avgHit = e.hits == 0 ? 0 : (double) e.dealt / e.hits;
		int lost = (int) Math.round(e.idleTicks() / (double) weapon * avgHit);
		String cost = lost > 0 ? " Across this fight that is about " + lost + " damage you never threw." : "";
		return new Point(String.format("You attacked every %.1f ticks with a %d tick weapon: %d%% slower than it can go.",
			gap, weapon, percent) + cost,
			"Click your next attack while the current one is still swinging, rather than waiting to see it land.");
	}

	/** Time spent not attacking. */
	private static Point idle(Encounter e)
	{
		int missed = e.missedAttacks();
		int attacks = e.attackTicks.size();
		if (missed < 3 || attacks == 0 || missed * 100 / (attacks + missed) < 15)
		{
			return null;
		}
		double avgHit = e.hits == 0 ? 0 : (double) e.dealt / e.hits;
		int lostDamage = (int) Math.round(missed * avgHit);
		int idleTicks = e.idleTicks();
		int idleSecs = (int) Math.round(idleTicks * 0.6);
		int eatTicks = e.eatIdleTicks();
		String tip;
		if (eatTicks * 5 >= idleTicks * 2)
		{
			tip = "About " + Math.round(eatTicks * 0.6) + " of those seconds were around healing. Eat right after your attack lands, "
				+ "or combo eat (food, then a karambwan straight after), so healing stops costing you swings.";
		}
		else if (e.takenByMove.size() > 1 || (e.takenByMove.size() == 1 && !e.takenByMove.containsKey("other")))
		{
			tip = "Click back onto the target the moment each mechanic ends, before you fix anything else.";
		}
		else
		{
			tip = "Nothing in this fight forced that gap, so it is all yours to take back: reclick the target "
				+ "as soon as you are in range again.";
		}
		return new Point("You went about " + idleSecs + " seconds without attacking, room for roughly " + missed
			+ " more attacks (about " + lostDamage + " damage). Some of that the fight forces on you; the rest is free damage.", tip);
	}

	private static int usualAccuracy(List<FightSummary> past)
	{
		List<FightSummary> last = past.subList(Math.max(0, past.size() - 10), past.size());
		double sum = 0;
		for (FightSummary s : last)
		{
			sum += s.accuracyPct;
		}
		return (int) Math.round(sum / last.size());
	}

	private static Point accuracyDrop(Encounter e, List<FightSummary> past)
	{
		if (e.hits < 20 || past.size() < 3)
		{
			return null;
		}
		int usual = usualAccuracy(past);
		if (usual - e.accuracyPct() >= 10)
		{
			return new Point("Only " + e.accuracyPct() + "% of your hits landed. Your usual here is " + usual + "%.",
				"Check your gear, your boosts and the attack style you had on before the next one.");
		}
		return null;
	}

	// ---------- strong points ----------

	private static String accuracyUp(Encounter e, List<FightSummary> past)
	{
		if (e.hits < 20 || past.size() < 3)
		{
			return null;
		}
		int usual = usualAccuracy(past);
		return e.accuracyPct() - usual >= 5
			? e.accuracyPct() + "% of your hits landed, up from your usual " + usual + "%." : null;
	}

	private static String lessDamage(Encounter e, List<FightSummary> kills)
	{
		if (e.outcome != Encounter.Outcome.KILL || kills.size() < 3 || e.taken == 0)
		{
			return null;
		}
		List<FightSummary> last = kills.subList(Math.max(0, kills.size() - 10), kills.size());
		double sum = 0;
		for (FightSummary s : last)
		{
			sum += s.taken;
		}
		long usual = Math.round(sum / last.size());
		return usual >= 20 && e.taken * 10 <= usual * 7
			? "You took " + e.taken + " damage against your usual " + usual + "." : null;
	}

	private static boolean isRecord(Encounter e, List<FightSummary> kills)
	{
		return e.outcome == Encounter.Outcome.KILL && kills.size() >= 2 && e.durationTicks() < best(kills);
	}

	private static int best(List<FightSummary> kills)
	{
		int best = Integer.MAX_VALUE;
		for (FightSummary s : kills)
		{
			best = Math.min(best, s.durationTicks);
		}
		return best;
	}

	/** The biggest hit that landed within a few ticks of a special attack, if it was a good one. */
	private static int bestSpecHit(Encounter e)
	{
		int bestHit = 0;
		for (Encounter.Event spec : e.events)
		{
			if (spec.kind != Encounter.Kind.SPEC)
			{
				continue;
			}
			for (Encounter.Event hit : e.events)
			{
				if (hit.kind == Encounter.Kind.DEALT && hit.tick >= spec.tick && hit.tick <= spec.tick + 6)
				{
					bestHit = Math.max(bestHit, hit.amount);
				}
			}
		}
		return bestHit >= 25 && bestHit * 5 >= e.maxHit * 4 ? bestHit : 0;
	}

	// ---------- banter ----------

	/** One short line for the situation. Decided by what happened, never at random. */
	static String vibe(Encounter e, boolean record)
	{
		if (e.outcome == Encounter.Outcome.DEATH)
		{
			if (e.targetHpPct >= 1 && e.targetHpPct <= 10)
			{
				return "so close </3";
			}
			return e.targetIsPlayer ? "gf </3" : "</3";
		}
		if (e.outcome != Encounter.Outcome.KILL)
		{
			return null;
		}
		if (record)
		{
			return "gz, new pb";
		}
		if (e.lowestHp >= 0 && e.maxHp > 0 && e.lowestHp <= Math.max(5, e.maxHp / 10))
		{
			return "clutch";
		}
		if (e.taken == 0)
		{
			return "ezpz";
		}
		return e.targetIsPlayer ? "gf" : null;
	}

	// ---------- numbers ----------

	private static void stats(Encounter e, Debrief d, List<FightSummary> kills)
	{
		if (e.hits > 0)
		{
			d.stats.add(String.format("Dealt %d in %s (%.1f per second). %d%% of %d hits landed, biggest %d.",
				e.dealt, clock(e.durationTicks()), e.dps(), e.accuracyPct(), e.hits, e.maxHit));
		}
		else
		{
			d.stats.add("You dealt no damage.");
		}
		String took = "Took " + e.taken + " in " + e.hitsTaken + (e.hitsTaken == 1 ? " hit" : " hits") + ", biggest " + e.maxTaken + ".";
		if (e.maxHp > 0 && e.taken > 0)
		{
			double bars = (double) e.taken / e.maxHp;
			took += bars < 0.1
				? " That barely scratched you."
				: String.format(" That is %.1f of your health bars.", bars);
		}
		if (e.lowestHp >= 0 && e.taken > 0)
		{
			took += " Lowest you got: " + e.lowestHp + " HP.";
		}
		d.stats.add(took);
		d.stats.add("Healed " + e.healed + " in " + e.heals + (e.heals == 1 ? " heal" : " heals") + ". Prayer used: "
			+ e.prayerUsed + ". Special attacks: " + e.specs + ".");
		// The hit count above is hitsplats (a spec can be two); this line is about cadence,
		// so it says how often you swung rather than repeating a second, different total.
		int weapon = e.weaponSpeed();
		double gap = e.averageGap();
		if (weapon > 0 && gap > 0)
		{
			String cadence = String.format("You swung every %.1f ticks; the weapon goes every %d.", gap, weapon);
			if (gap <= weapon + 0.25)
			{
				cadence = String.format("You swung every %.1f ticks, which is the weapon's %d.", gap, weapon);
			}
			d.stats.add(cadence + " Time not attacking: " + Math.round(e.idleTicks() * 0.6) + "s.");
		}
		else if (e.attackSpeed() > 0)
		{
			d.stats.add("You swung every " + e.attackSpeed() + " ticks while you were on it. Time not attacking: "
				+ Math.round(e.idleTicks() * 0.6) + "s.");
		}
		if (e.outcome == Encounter.Outcome.KILL && kills.size() >= 3)
		{
			List<FightSummary> last = kills.subList(Math.max(0, kills.size() - 10), kills.size());
			double time = 0;
			double taken = 0;
			for (FightSummary s : last)
			{
				time += s.durationTicks;
				taken += s.taken;
			}
			d.stats.add("Against your last " + last.size() + " kills: time " + clock(e.durationTicks()) + " (average "
				+ clock((int) Math.round(time / last.size())) + "), damage taken " + e.taken + " (average "
				+ Math.round(taken / last.size()) + ").");
		}
	}

	// ---------- you versus them ----------

	private static final class Line
	{
		final int tick;
		final String you;
		final String them;
		/** Lines with a weight can be dropped (smallest first) when the story runs long. */
		final int weight;

		Line(int tick, String you, String them, int weight)
		{
			this.tick = tick;
			this.you = you;
			this.them = them;
			this.weight = weight;
		}
	}

	private static void timeline(Encounter e, Debrief d, Function<String, String> moveNames)
	{
		// Oldest first, with the ending always last (List.sort keeps same-tick events in the order they came)
		List<Encounter.Event> ev = new ArrayList<>(e.events);
		ev.sort(Comparator.comparingInt(x -> x.kind == Encounter.Kind.END ? Integer.MAX_VALUE : x.tick));

		List<Integer> specTicks = new ArrayList<>();
		for (Encounter.Event x : ev)
		{
			if (x.kind == Encounter.Kind.SPEC)
			{
				specTicks.add(x.tick);
			}
		}
		int bigHit = Math.max(20, e.maxHit * 7 / 10);

		List<Line> lines = new ArrayList<>();
		String ending = null;
		int endTick = e.endTick;
		for (int i = 0; i < ev.size(); i++)
		{
			Encounter.Event x = ev.get(i);
			switch (x.kind)
			{
				case TOOK:
				{
					// Hits from the same move within a couple of ticks read as one moment
					int sum = x.amount;
					int n = 1;
					while (i + 1 < ev.size() && ev.get(i + 1).kind == Encounter.Kind.TOOK
						&& ev.get(i + 1).tick - x.tick <= 2 && ev.get(i + 1).note.equals(x.note))
					{
						sum += ev.get(++i).amount;
						n++;
					}
					// The main opponent's ordinary hits need no name: the column is already theirs
					String named = namedMove(x.note, moveNames);
					String what;
					if (x.note != null && x.note.startsWith("@"))
					{
						// Another player: their name, unless they are the one you are fighting
						what = x.note.equals("@" + e.target) ? "hit " + sum : sum + " " + x.note.substring(1);
					}
					else
					{
						what = named == null ? "hit " + sum : sum + " " + named;
					}
					lines.add(new Line(x.tick, "", what + (n > 1 ? " x" + n : ""), sum));
					break;
				}
				case DEALT:
				{
					boolean fromSpec = false;
					for (int s : specTicks)
					{
						fromSpec |= x.tick >= s && x.tick <= s + 6;
					}
					if (fromSpec)
					{
						lines.add(new Line(x.tick, "spec " + x.amount, "", 0));
					}
					else if (x.amount >= bigHit)
					{
						lines.add(new Line(x.tick, "hit " + x.amount, "", x.amount));
					}
					break;
				}
				case HEAL:
				{
					int sum = x.amount;
					while (i + 1 < ev.size() && ev.get(i + 1).kind == Encounter.Kind.HEAL && ev.get(i + 1).tick - x.tick <= 2)
					{
						sum += ev.get(++i).amount;
					}
					lines.add(new Line(x.tick, "ate +" + sum, "", sum));
					break;
				}
				case SPEC:
				{
					// Only worth its own line if no hit followed it
					boolean landed = false;
					for (Encounter.Event h : ev)
					{
						landed |= h.kind == Encounter.Kind.DEALT && h.tick >= x.tick && h.tick <= x.tick + 6;
					}
					if (!landed)
					{
						lines.add(new Line(x.tick, "spec miss", "", 0));
					}
					break;
				}
				case LOW_HP:
					lines.add(new Line(x.tick, x.amount + " hp left", "", 0));
					break;
				case LOOT:
					break; // shown on the ending line
				case TARGET_HP:
					lines.add(new Line(x.tick, "", "at " + x.amount + "%", 0));
					break;
				default:
					endTick = x.tick;
					ending = e.outcome == Encounter.Outcome.KILL ? "KILL" : e.outcome == Encounter.Outcome.DEATH ? "YOU DIED" : "fight ended";
			}
		}
		int dropped = 0;
		while (lines.size() > MAX_TIMELINE_LINES - 2)
		{
			Line smallest = lines.stream().filter(l -> l.weight > 0).min(Comparator.comparingInt(l -> l.weight)).orElse(null);
			if (smallest == null)
			{
				break;
			}
			lines.remove(smallest);
			dropped++;
		}
		String them = e.target.length() > LEFT_WIDTH ? e.target.substring(0, LEFT_WIDTH) : e.target;
		d.timeline.add("     " + pad("YOU") + "| " + them.toUpperCase());
		for (Line l : lines)
		{
			d.timeline.add((clock(l.tick - e.startTick) + " " + pad(l.you) + "| " + l.them).trim());
		}
		if (ending != null)
		{
			d.timeline.add(clock(endTick - e.startTick) + " " + ending
				+ (e.outcome == Encounter.Outcome.KILL && e.lootValue > 0 ? " +" + gp(e.lootValue) : ""));
		}
		if (dropped > 0)
		{
			d.timeline.add("(" + dropped + " smaller moments left out)");
		}
	}

	private static String pad(String s)
	{
		StringBuilder sb = new StringBuilder(s);
		while (sb.length() < LEFT_WIDTH)
		{
			sb.append(' ');
		}
		return sb.toString();
	}

	// ---------- wording helpers ----------

	/** "during swipe" / "during move 14322" / "from untracked damage". */
	private static String during(String key, Function<String, String> moveNames)
	{
		if ("other".equals(key))
		{
			return "from untracked damage";
		}
		if (key.startsWith("@"))
		{
			return "from " + key.substring(1);
		}
		return "during " + moveLabel(key, moveNames);
	}

	/** The move's name if it has one (nickname first, then the built-in list), else null. */
	static String namedMove(String key, Function<String, String> moveNames)
	{
		if (key == null || "other".equals(key) || key.startsWith("@"))
		{
			return null;
		}
		String nick = moveNames == null ? null : moveNames.apply(key);
		if (nick != null && !nick.isEmpty())
		{
			return nick;
		}
		return KNOWN_MOVES.get(key);
	}

	/** The player's own nickname wins, then the built-in special attack names, then a plain description. */
	static String moveLabel(String key, Function<String, String> moveNames)
	{
		if ("other".equals(key))
		{
			return "untracked";
		}
		if (key.startsWith("@"))
		{
			return key.substring(1);
		}
		String nick = moveNames == null ? null : moveNames.apply(key);
		if (nick != null && !nick.isEmpty())
		{
			return nick;
		}
		String known = KNOWN_MOVES.get(key);
		if (known != null)
		{
			return known;
		}
		// An animation nobody has named yet. The number means nothing to a player,
		// so describe it instead and let the tip say how to name it.
		return "an attack of its own";
	}

	/** Game ticks as m:ss. */
	static String clock(int ticks)
	{
		int secs = (int) Math.round(Math.max(0, ticks) * 0.6);
		return (secs / 60) + ":" + String.format("%02d", secs % 60);
	}

	static String gp(long gp)
	{
		if (gp >= 1_000_000_000)
		{
			return String.format("%.1fb", gp / 1e9);
		}
		if (gp >= 1_000_000)
		{
			return String.format("%.1fm", gp / 1e6);
		}
		if (gp >= 1_000)
		{
			return (gp / 1_000) + "k";
		}
		return gp + "gp";
	}
}

package com.retrospect;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Everything recorded about one fight, from first hit to the end. */
final class Encounter
{
	enum Outcome
	{
		KILL, DEATH, LEFT
	}

	enum Kind
	{
		TOOK, DEALT, HEAL, SPEC, TARGET_HP, LOW_HP, LOOT, END
	}

	/** One thing that happened, with the tick it happened on. */
	static final class Event
	{
		final int tick;
		final Kind kind;
		final int amount;
		final String note;

		Event(int tick, Kind kind, int amount, String note)
		{
			this.tick = tick;
			this.kind = kind;
			this.amount = amount;
			this.note = note;
		}
	}

	String target;
	/** The game's id for the monster, or -1 for a player. */
	int targetId = -1;
	boolean targetIsPlayer;
	/** Every player you traded hits with, in the order they joined. */
	final Set<String> opponents = new LinkedHashSet<>();
	long startedAtMs;
	int startTick;
	int endTick;
	Outcome outcome = Outcome.LEFT;

	int dealt;
	int hits;
	int zeros;
	int maxHit;

	int taken;
	int hitsTaken;
	int maxTaken;

	int healed;
	int heals;
	int lastHealTick = -1;
	int prayerUsed;
	int specs;
	/** Lowest your hitpoints got. -1 = never seen. */
	int lowestHp = -1;
	/** Times you fell under a quarter of your health. */
	int lowDips;
	/** Times you healed while already above 80% health. */
	int earlyEats;
	/** Value of what the kill dropped, in gp. */
	long lootValue;

	/** Your hitpoints level, so damage can be read against your health bar. 0 = unknown. */
	int maxHp;
	/** Target health in percent the last time it was seen. -1 = unknown. */
	int targetHpPct = -1;

	/** Ticks on which you started an attack. */
	final List<Integer> attackTicks = new ArrayList<>();
	/** The equipped weapon's attack speed at each of those ticks, 0 where it was not known. */
	final List<Integer> weaponTicks = new ArrayList<>();
	/** Damage dealt per target name, to work out who the fight was really against. */
	final Map<String, Integer> dealtByName = new LinkedHashMap<>();
	/** Move -> {times it hit you, total damage}. */
	final Map<String, int[]> takenByMove = new LinkedHashMap<>();
	final List<Event> events = new ArrayList<>();

	int durationTicks()
	{
		return Math.max(1, endTick - startTick);
	}

	double seconds()
	{
		return durationTicks() * 0.6;
	}

	double dps()
	{
		return dealt / seconds();
	}

	/** Share of your hits that did damage, 0-100. */
	int accuracyPct()
	{
		return hits == 0 ? 0 : (int) Math.round(100.0 * (hits - zeros) / hits);
	}

	/**
	 * Your weapon's attack speed in ticks, read from the fight itself:
	 * the most common gap between your attacks.
	 */
	int attackSpeed()
	{
		int[] count = new int[11];
		for (int i = 1; i < attackTicks.size(); i++)
		{
			int gap = attackTicks.get(i) - attackTicks.get(i - 1);
			if (gap >= 2 && gap <= 10)
			{
				count[gap]++;
			}
		}
		int best = 0;
		for (int gap = 2; gap <= 10; gap++)
		{
			if (count[gap] > count[best])
			{
				best = gap;
			}
		}
		return count[best] >= 3 ? best : 0;
	}

	/**
	 * The weapon's own attack speed, as the game reports it, rather than the rhythm you
	 * happened to keep. Modal value, so a mid-fight weapon switch does not skew it.
	 */
	int weaponSpeed()
	{
		int[] count = new int[11];
		int best = 0;
		for (int ticks : weaponTicks)
		{
			if (ticks >= 1 && ticks <= 10)
			{
				count[ticks]++;
				if (count[ticks] > count[best])
				{
					best = ticks;
				}
			}
		}
		return best;
	}

	/**
	 * What one attack should cost: the real weapon speed when the game told us, and
	 * otherwise the rhythm we observed. Measuring against the weapon matters: against
	 * your own rhythm, being consistently slow looks like being on time.
	 */
	int expectedSpeed()
	{
		int weapon = weaponSpeed();
		return weapon > 0 ? weapon : attackSpeed();
	}

	/** The weapon speed in force at a given attack, falling back to the fight's usual one. */
	private int speedAt(int index)
	{
		if (index >= 0 && index < weaponTicks.size())
		{
			int ticks = weaponTicks.get(index);
			if (ticks >= 1 && ticks <= 10)
			{
				return ticks;
			}
		}
		return expectedSpeed();
	}

	/** Average ticks between your attacks, or 0 with fewer than two attacks. */
	double averageGap()
	{
		if (attackTicks.size() < 2)
		{
			return 0;
		}
		int span = attackTicks.get(attackTicks.size() - 1) - attackTicks.get(0);
		return (double) span / (attackTicks.size() - 1);
	}

	/** Ticks spent not attacking beyond what the weapon needs. Includes time the fight forced on you. */
	int idleTicks()
	{
		if (expectedSpeed() == 0)
		{
			return 0;
		}
		int idle = 0;
		for (int i = 1; i < attackTicks.size(); i++)
		{
			int gap = attackTicks.get(i) - attackTicks.get(i - 1);
			int speed = speedAt(i - 1);
			if (speed > 0 && gap > speed)
			{
				idle += gap - speed;
			}
		}
		return idle;
	}

	/** The part of the idle time that fell in gaps where you healed. */
	int eatIdleTicks()
	{
		if (expectedSpeed() == 0)
		{
			return 0;
		}
		int idle = 0;
		for (int i = 1; i < attackTicks.size(); i++)
		{
			int from = attackTicks.get(i - 1);
			int to = attackTicks.get(i);
			int speed = speedAt(i - 1);
			if (speed <= 0 || to - from <= speed)
			{
				continue;
			}
			for (Event ev : events)
			{
				if (ev.kind == Kind.HEAL && ev.tick >= from && ev.tick <= to)
				{
					idle += to - from - speed;
					break;
				}
			}
		}
		return idle;
	}

	/** A sensible health floor to eat at: just above the biggest hit you took. */
	int eatFloor()
	{
		return maxTaken + 5;
	}

	/** How many attacks would have fitted in the idle time. */
	int missedAttacks()
	{
		int speed = expectedSpeed();
		return speed == 0 ? 0 : idleTicks() / speed;
	}

	/** The move that did the most damage to you, or null. */
	String worstMove()
	{
		String worst = null;
		int most = 0;
		for (Map.Entry<String, int[]> e : takenByMove.entrySet())
		{
			if (e.getValue()[1] > most)
			{
				most = e.getValue()[1];
				worst = e.getKey();
			}
		}
		return worst;
	}
}

package com.retrospect;

/**
 * Follows one fight at a time. The plugin feeds it what it sees in game;
 * it decides when a fight starts and when it is over.
 * Holds no game objects, so it can be tested on its own.
 */
final class EncounterTracker
{
	private Encounter current;
	private int lastActivityTick;
	/** A special attack used in the moment before the fight registered. */
	private static final int NO_TICK = Integer.MIN_VALUE;
	private static final int SPEC_GRACE_TICKS = 3;
	private int pendingSpecTick = NO_TICK;
	/** The swing that started the fight, which lands before the first hitsplat registers it. */
	private int pendingAttackTick = NO_TICK;
	private int pendingAttackSpeed = 0;
	/** Tick the target died on, or -1. The fight closes a few ticks later so the last hits are counted. */
	private int deathTick = -1;
	private Encounter.Outcome pendingOutcome;
	private int idleTimeoutTicks = 50;
	private int lastHpMilestone = 100;
	private int hp = -1;

	void setIdleTimeoutTicks(int ticks)
	{
		idleTimeoutTicks = Math.max(10, ticks);
	}

	boolean isActive()
	{
		return current != null;
	}

	Encounter getCurrent()
	{
		return current;
	}

	private void ensure(int tick, String name, boolean isPlayer, int maxHp, long nowMs)
	{
		if (current != null)
		{
			return;
		}
		current = new Encounter();
		current.target = name;
		current.targetIsPlayer = isPlayer;
		current.startTick = tick;
		current.startedAtMs = nowMs;
		current.maxHp = maxHp;
		lastActivityTick = tick;
		deathTick = -1;
		pendingOutcome = null;
		lastHpMilestone = 100;
		if (pendingSpecTick != NO_TICK && tick - pendingSpecTick <= SPEC_GRACE_TICKS)
		{
			current.specs++;
			current.events.add(new Encounter.Event(pendingSpecTick, Encounter.Kind.SPEC, 0, null));
		}
		pendingSpecTick = NO_TICK;
		if (pendingAttackTick != NO_TICK && tick - pendingAttackTick <= SPEC_GRACE_TICKS)
		{
			current.attackTicks.add(pendingAttackTick);
			current.weaponTicks.add(pendingAttackSpeed);
		}
		pendingAttackTick = NO_TICK;
		pendingAttackSpeed = 0;
		if (hp >= 0)
		{
			current.lowestHp = hp;
		}
	}

	/** One of your hitsplats landed on something. */
	void onMyHit(int tick, int amount, String targetName, int targetId, boolean isPlayer, int targetHpPct, int maxHp, long nowMs)
	{
		if (targetName == null)
		{
			return;
		}
		boolean fresh = current == null;
		ensure(tick, targetName, isPlayer, maxHp, nowMs);
		Encounter e = current;
		if (fresh)
		{
			e.targetId = isPlayer ? -1 : targetId;
		}
		if (isPlayer)
		{
			e.opponents.add(targetName);
		}
		if (amount > 0)
		{
			e.events.add(new Encounter.Event(tick, Encounter.Kind.DEALT, amount, targetName));
		}
		e.dealt += amount;
		e.hits++;
		if (amount == 0)
		{
			e.zeros++;
		}
		e.maxHit = Math.max(e.maxHit, amount);
		int total = e.dealtByName.merge(targetName, amount, Integer::sum);
		// The fight is "against" whoever you have hurt the most (bosses with minions)
		Integer lead = e.dealtByName.get(e.target);
		if (!targetName.equals(e.target) && (lead == null || total > lead))
		{
			e.target = targetName;
			e.targetIsPlayer = isPlayer;
			e.targetId = isPlayer ? -1 : targetId;
			lastHpMilestone = 100;
		}
		if (targetName.equals(e.target))
		{
			onTargetHp(tick, targetHpPct);
		}
		lastActivityTick = tick;
	}

	/** You took damage. attackerName may be null if nobody obvious did it (poison, floor damage). */
	void onHitTaken(int tick, int amount, String attackerName, boolean attackerIsPlayer, String move, int maxHp, long nowMs)
	{
		if (current == null)
		{
			if (attackerName == null || amount <= 0)
			{
				return;
			}
			ensure(tick, attackerName, attackerIsPlayer, maxHp, nowMs);
		}
		Encounter e = current;
		if (attackerIsPlayer && attackerName != null)
		{
			e.opponents.add(attackerName);
		}
		e.taken += amount;
		e.hitsTaken++;
		e.maxTaken = Math.max(e.maxTaken, amount);
		String key = move == null ? "other" : move;
		int[] agg = e.takenByMove.computeIfAbsent(key, k -> new int[2]);
		agg[0]++;
		agg[1] += amount;
		if (amount > 0)
		{
			e.events.add(new Encounter.Event(tick, Encounter.Kind.TOOK, amount, key));
		}
		lastActivityTick = tick;
	}

	/** You started an attack animation at your target. */
	void onMyAttack(int tick)
	{
		onMyAttack(tick, 0);
	}

	/** @param weaponTicks the equipped weapon's attack speed, or 0 if it could not be read */
	void onMyAttack(int tick, int weaponTicks)
	{
		if (current == null)
		{
			pendingAttackTick = tick;
			pendingAttackSpeed = weaponTicks;
			return;
		}
		if (current.attackTicks.isEmpty() || current.attackTicks.get(current.attackTicks.size() - 1) != tick)
		{
			current.attackTicks.add(tick);
			current.weaponTicks.add(weaponTicks);
		}
		lastActivityTick = tick;
	}

	/** Your hitpoints right now. Call whenever they change, in or out of a fight. */
	void onHp(int tick, int newHp)
	{
		int before = hp;
		hp = newHp;
		// After you die your health snaps back to full: that is the respawn, not part of the fight
		if (current == null || newHp < 0 || pendingOutcome == Encounter.Outcome.DEATH)
		{
			return;
		}
		Encounter e = current;
		if (e.lowestHp < 0 || newHp < e.lowestHp)
		{
			e.lowestHp = newHp;
		}
		int quarter = e.maxHp / 4;
		if (quarter > 0 && newHp > 0 && newHp <= quarter && (before < 0 || before > quarter))
		{
			e.lowDips++;
			e.events.add(new Encounter.Event(tick, Encounter.Kind.LOW_HP, newHp, null));
		}
	}

	/** The kill dropped something. Counted while the fight is still being wrapped up. */
	void onLoot(int tick, long value)
	{
		if (current != null && value > 0)
		{
			current.lootValue += value;
			current.events.add(new Encounter.Event(tick, Encounter.Kind.LOOT, (int) Math.min(Integer.MAX_VALUE, value), null));
		}
	}

	/**
	 * @param hpAfter your hitpoints after the heal, or -1 if unknown
	 */
	void onHeal(int tick, int amount, int hpAfter)
	{
		if (current == null || amount <= 0 || pendingOutcome == Encounter.Outcome.DEATH)
		{
			return;
		}
		if (hpAfter >= 0 && current.maxHp > 0 && (hpAfter - amount) * 5 >= current.maxHp * 4)
		{
			current.earlyEats++;
		}
		current.healed += amount;
		current.heals++;
		current.lastHealTick = tick;
		current.events.add(new Encounter.Event(tick, Encounter.Kind.HEAL, amount, null));
	}

	void onPrayerUsed(int amount)
	{
		if (current != null && amount > 0)
		{
			current.prayerUsed += amount;
		}
	}

	void onSpec(int tick)
	{
		if (current == null)
		{
			// Opening a fight with a spec fires this before the first hitsplat starts
			// the encounter. Hold it, and count it once the fight actually begins.
			pendingSpecTick = tick;
			return;
		}
		current.specs++;
		current.events.add(new Encounter.Event(tick, Encounter.Kind.SPEC, 0, null));
	}

	/** Target health in percent. Logs a line each time it crosses 75, 50 and 25. */
	void onTargetHp(int tick, int pct)
	{
		if (current == null || pct < 0)
		{
			return;
		}
		current.targetHpPct = pct;
		// One big hit can cross several marks at once: only the lowest is worth a line
		int crossed = -1;
		for (int mark : new int[]{75, 50, 25})
		{
			if (pct <= mark && lastHpMilestone > mark)
			{
				crossed = mark;
			}
		}
		if (crossed > 0 && pct > 0)
		{
			current.events.add(new Encounter.Event(tick, Encounter.Kind.TARGET_HP, crossed, null));
		}
		lastHpMilestone = Math.min(lastHpMilestone, pct);
	}

	/** Something died. Only matters if it is the thing you are fighting. */
	void onActorDeath(int tick, String name)
	{
		if (current != null && name != null && name.equals(current.target) && pendingOutcome == null)
		{
			pendingOutcome = Encounter.Outcome.KILL;
			deathTick = tick;
			current.targetHpPct = 0;
		}
	}

	void onMyDeath(int tick)
	{
		if (current != null)
		{
			pendingOutcome = Encounter.Outcome.DEATH;
			deathTick = tick;
		}
	}

	/** Call once per game tick. Returns the finished fight when one has just ended, otherwise null. */
	Encounter onTick(int tick)
	{
		if (current == null)
		{
			return null;
		}
		// Stay open a few ticks after a death so the last hits and the loot are counted
		int wrapUp = current.targetIsPlayer ? 8 : 5;
		if (pendingOutcome != null && tick >= deathTick + wrapUp)
		{
			return finish(deathTick, pendingOutcome);
		}
		if (pendingOutcome == null && tick - lastActivityTick > idleTimeoutTicks)
		{
			return finish(lastActivityTick, Encounter.Outcome.LEFT);
		}
		return null;
	}

	/** Ends whatever is in progress right now (logout, plugin switched off). */
	Encounter forceEnd(int tick)
	{
		if (current == null)
		{
			return null;
		}
		return pendingOutcome != null ? finish(deathTick, pendingOutcome) : finish(Math.max(lastActivityTick, current.startTick), Encounter.Outcome.LEFT);
	}

	private Encounter finish(int endTick, Encounter.Outcome outcome)
	{
		Encounter e = current;
		e.endTick = Math.max(endTick, e.startTick + 1);
		e.outcome = outcome;
		e.events.add(new Encounter.Event(e.endTick, Encounter.Kind.END, 0, null));
		current = null;
		pendingOutcome = null;
		deathTick = -1;
		return e;
	}
}

package com.retrospect;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.runelite.client.util.Filepath;

/**
 * One folder per thing you fight. In Serious mode a fight's debrief and clips are filed
 * into its folder; each folder carries its own switches for what gets kept.
 */
final class FightFolders
{
	static final class Folder
	{
		String key;
		String name;
		/** The game's id for the monster the first time it was seen, or -1. */
		int npcId = -1;
		/** Made by the player with "+ Create custom". */
		boolean custom;
		/** For custom folders: the names that are filed here, separated by commas. */
		String targets;
		/** Folder name on disk. */
		String dir;
		boolean log = true;
		boolean clipKills;
		boolean clipDeaths = true;
		int fights;
		int kills;
		int deaths;
		int bestTicks;

		boolean claims(String target)
		{
			if (!custom || targets == null || target == null)
			{
				return false;
			}
			for (String t : targets.split(","))
			{
				if (!t.trim().isEmpty() && t.trim().equalsIgnoreCase(target.trim()))
				{
					return true;
				}
			}
			return false;
		}

		String statsLine()
		{
			if (fights == 0)
			{
				return "No fights filed yet";
			}
			return fights + (fights == 1 ? " fight" : " fights") + " \u00b7 " + kills + (kills == 1 ? " kill" : " kills")
				+ " \u00b7 " + deaths + (deaths == 1 ? " death" : " deaths")
				+ (bestTicks > 0 ? " \u00b7 best " + DebriefBuilder.clock(bestTicks) : "");
		}
	}

	private final Filepath file;
	private final Gson gson;
	private List<Folder> folders = new ArrayList<>();

	FightFolders(Filepath file, Gson gson)
	{
		this.file = file;
		this.gson = gson;
	}

	synchronized void load()
	{
		folders = new ArrayList<>();
		try
		{
			if (file.isFile())
			{
				List<Folder> read;
				try (Reader r = file.openBufferedReader())
				{
					read = gson.fromJson(r, new TypeToken<List<Folder>>()
					{
					}.getType());
				}
				if (read != null)
				{
					for (Folder f : read)
					{
						if (f != null && f.key != null && f.name != null && f.dir != null)
						{
							folders.add(f);
						}
					}
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			folders = new ArrayList<>();
		}
	}

	synchronized void save() throws IOException
	{
		file.getParent().createDirectories();
		file.write(gson.toJson(folders));
	}

	synchronized List<Folder> all()
	{
		return new ArrayList<>(folders);
	}

	/**
	 * The folder a fight belongs in. A custom folder that names the target wins; every player
	 * fight shares one PvP folder; otherwise each monster gets its own, made the first time
	 * you fight it.
	 *
	 * @param create make the folder if it does not exist yet
	 */
	synchronized Folder forFight(String target, int npcId, boolean isPlayer, boolean create)
	{
		if (target == null)
		{
			return null;
		}
		for (Folder f : folders)
		{
			if (f.claims(target))
			{
				return f;
			}
		}
		String key = isPlayer ? "pvp" : "name:" + target.toLowerCase(Locale.ROOT);
		for (Folder f : folders)
		{
			if (f.key.equals(key))
			{
				return f;
			}
		}
		if (!create)
		{
			return null;
		}
		Folder f = new Folder();
		f.key = key;
		f.name = isPlayer ? "PvP" : target;
		f.npcId = isPlayer ? -1 : npcId;
		f.dir = uniqueDir(isPlayer ? "PvP" : target + (npcId >= 0 ? " [" + npcId + "]" : ""));
		folders.add(f);
		return f;
	}

	/** Returns the new folder, or null if the name is empty. */
	synchronized Folder createCustom(String name, String targets)
	{
		String clean = name == null ? "" : name.trim();
		if (clean.isEmpty())
		{
			return null;
		}
		Folder f = new Folder();
		f.key = "custom:" + System.nanoTime();
		f.name = clean.length() > 40 ? clean.substring(0, 40) : clean;
		f.custom = true;
		f.targets = targets == null ? "" : targets.trim();
		f.dir = uniqueDir(f.name);
		folders.add(0, f);
		return f;
	}

	synchronized void record(Folder f, Encounter e)
	{
		f.fights++;
		if (e.outcome == Encounter.Outcome.KILL)
		{
			f.kills++;
			if (f.bestTicks == 0 || e.durationTicks() < f.bestTicks)
			{
				f.bestTicks = e.durationTicks();
			}
		}
		else if (e.outcome == Encounter.Outcome.DEATH)
		{
			f.deaths++;
		}
	}

	/** A name that is safe on disk and not already used by another folder. */
	private String uniqueDir(String wanted)
	{
		String base = dirName(wanted);
		String name = base;
		int n = 2;
		while (taken(name))
		{
			name = base + " (" + n++ + ")";
		}
		return name;
	}

	private boolean taken(String dir)
	{
		for (Folder f : folders)
		{
			if (f.dir.equalsIgnoreCase(dir))
			{
				return true;
			}
		}
		return false;
	}

	/** Keeps letters, digits, spaces and a few safe marks. Never empty, never a path. */
	static String dirName(String wanted)
	{
		String s = wanted == null ? "" : wanted.replaceAll("[^A-Za-z0-9 _\\-\\[\\]'()]+", " ").replaceAll("\\s+", " ").trim();
		while (s.endsWith(".") || s.endsWith(" "))
		{
			s = s.substring(0, s.length() - 1);
		}
		if (s.length() > 50)
		{
			s = s.substring(0, 50).trim();
		}
		return s.isEmpty() ? "Folder" : s;
	}
}

package com.retrospect;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.util.Filepath;

/** Past fights, kept in one small file so they survive restarts. */
final class FightHistory
{
	static final int MAX_ENTRIES = 1000;

	private final Filepath file;
	private final Gson gson;
	private List<FightSummary> entries = new ArrayList<>();

	FightHistory(Filepath file, Gson gson)
	{
		this.file = file;
		this.gson = gson;
	}

	synchronized void load()
	{
		entries = new ArrayList<>();
		if (!file.isFile())
		{
			return;
		}
		try
		{
			List<FightSummary> read;
			try (Reader r = file.openBufferedReader())
			{
				read = gson.fromJson(r, new TypeToken<List<FightSummary>>()
				{
				}.getType());
			}
			if (read != null)
			{
				for (FightSummary s : read)
				{
					if (s != null && s.target != null)
					{
						entries.add(s);
					}
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			// A damaged history file should never stop the plugin; start fresh and keep the old one aside
			Filepath aside = file.getParent().join(file.getFileName() + ".unreadable");
			try
			{
				file.copyTo(aside, StandardCopyOption.REPLACE_EXISTING);
			}
			catch (IOException ignored)
			{
				// nothing more to do
			}
		}
	}

	synchronized void add(FightSummary s) throws IOException
	{
		entries.add(s);
		while (entries.size() > MAX_ENTRIES)
		{
			entries.remove(0);
		}
		file.getParent().createDirectories();
		Filepath tmp = file.getParent().join(file.getFileName() + ".tmp");
		tmp.write(gson.toJson(entries));
		tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
	}

	/** Earlier fights against the same target, oldest first. */
	synchronized List<FightSummary> against(String target)
	{
		List<FightSummary> out = new ArrayList<>();
		for (FightSummary s : entries)
		{
			if (s.target.equalsIgnoreCase(target))
			{
				out.add(s);
			}
		}
		return out;
	}

	/** Most recent fights first. */
	synchronized List<FightSummary> recent(int limit)
	{
		List<FightSummary> out = new ArrayList<>();
		for (int i = entries.size() - 1; i >= 0 && out.size() < limit; i--)
		{
			out.add(entries.get(i));
		}
		return out;
	}
}

package com.retrospect;

/** The few numbers kept about each past fight, so new fights can be compared with old ones. */
final class FightSummary
{
	String target;
	long startedAtMs;
	String outcome;
	int durationTicks;
	int dealt;
	int taken;
	int accuracyPct;
	int missedAttacks;
	String takeaway;
	String clip;

	static FightSummary of(Encounter e, String takeaway, String clip)
	{
		FightSummary s = new FightSummary();
		s.target = e.target;
		s.startedAtMs = e.startedAtMs;
		s.outcome = e.outcome.name();
		s.durationTicks = e.durationTicks();
		s.dealt = e.dealt;
		s.taken = e.taken;
		s.accuracyPct = e.accuracyPct();
		s.missedAttacks = e.missedAttacks();
		s.takeaway = takeaway;
		s.clip = clip;
		return s;
	}

	boolean isKill()
	{
		return "KILL".equals(outcome);
	}
}

package com.retrospect;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.MemoryCacheImageOutputStream;

/**
 * Keeps the last few seconds of the game screen in memory as small JPEGs.
 * Nothing is written to disk until a moment is worth saving.
 */
final class FrameBuffer
{
	/** One captured frame: when it was taken and its JPEG bytes. */
	static final class Frame
	{
		final long timeMs;
		final byte[] jpeg;
		final int width;
		final int height;

		Frame(long timeMs, byte[] jpeg, int width, int height)
		{
			this.timeMs = timeMs;
			this.jpeg = jpeg;
			this.width = width;
			this.height = height;
		}
	}

	/** Memory ceiling until the settings say otherwise. RuneLite runs with 768 MB in total by default. */
	static final long DEFAULT_MAX_BYTES = 64L * 1024 * 1024;

	private final ArrayDeque<Frame> frames = new ArrayDeque<>();
	private long bytes;
	private long keepMs = 20_000;
	private long maxBytes = DEFAULT_MAX_BYTES;

	synchronized void setKeepMs(long keepMs)
	{
		this.keepMs = Math.max(1_000, keepMs);
	}

	/** When the buffer would grow past this, the oldest frames go first, so clips get shorter instead of the client running out of memory. */
	synchronized void setMaxBytes(long maxBytes)
	{
		this.maxBytes = Math.max(8L * 1024 * 1024, maxBytes);
	}

	synchronized long getBytes()
	{
		return bytes;
	}

	synchronized int size()
	{
		return frames.size();
	}

	synchronized void clear()
	{
		frames.clear();
		bytes = 0;
	}

	/** Shrinks, compresses and stores one frame. Safe to call from a background thread. */
	void add(Image image, long timeMs, int maxHeight, float quality) throws IOException
	{
		BufferedImage scaled = scale(image, maxHeight);
		byte[] jpeg = toJpeg(scaled, quality);
		Frame frame = new Frame(timeMs, jpeg, scaled.getWidth(), scaled.getHeight());
		synchronized (this)
		{
			frames.addLast(frame);
			bytes += jpeg.length;
			while (!frames.isEmpty() && (frames.peekFirst().timeMs < timeMs - keepMs || bytes > maxBytes))
			{
				bytes -= frames.removeFirst().jpeg.length;
			}
		}
	}

	/** Copies out every frame between the two times (inclusive), oldest first. */
	synchronized List<Frame> snapshot(long fromMs, long toMs)
	{
		List<Frame> out = new ArrayList<>();
		for (Frame f : frames)
		{
			if (f.timeMs >= fromMs && f.timeMs <= toMs)
			{
				out.add(f);
			}
		}
		return out;
	}

	/** Scales down to at most maxHeight, keeping the shape, with even width and height (video needs that). */
	static BufferedImage scale(Image image, int maxHeight)
	{
		int w = image.getWidth(null);
		int h = image.getHeight(null);
		if (w <= 0 || h <= 0)
		{
			throw new IllegalArgumentException("empty frame");
		}
		double ratio = h > maxHeight ? (double) maxHeight / h : 1.0;
		int tw = Math.max(2, (int) Math.round(w * ratio) & ~1);
		int th = Math.max(2, (int) Math.round(h * ratio) & ~1);
		BufferedImage out = new BufferedImage(tw, th, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(image, 0, 0, tw, th, null);
		g.dispose();
		return out;
	}

	static byte[] toJpeg(BufferedImage image, float quality) throws IOException
	{
		ImageWriter writer = ImageIO.getImageWritersByFormatName("jpg").next();
		try
		{
			ImageWriteParam param = writer.getDefaultWriteParam();
			param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
			param.setCompressionQuality(Math.max(0.3f, Math.min(0.95f, quality)));
			ByteArrayOutputStream bytes = new ByteArrayOutputStream(96 * 1024);
			try (MemoryCacheImageOutputStream out = new MemoryCacheImageOutputStream(bytes))
			{
				writer.setOutput(out);
				writer.write(null, new IIOImage(image, null, null), param);
			}
			return bytes.toByteArray();
		}
		finally
		{
			writer.dispose();
		}
	}
}

package com.retrospect;

import com.google.gson.Gson;
import java.awt.Color;
import java.io.IOException;
import java.io.Reader;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.client.util.Filepath;

/** The player's own wording and colours for the panel, with the stock look to fall back on. */
final class PanelLook
{
	static final int MAX_LABEL = 40;

	/** Heading key -> stock text, in the order the panel shows them. */
	static final Map<String, String> STOCK_LABELS = new LinkedHashMap<>();
	/** Colour key -> stock hex. */
	static final Map<String, String> STOCK_COLORS = new LinkedHashMap<>();
	/** Colour key -> what it is called on the Customize tab. */
	static final Map<String, String> COLOR_NAMES = new LinkedHashMap<>();

	static
	{
		STOCK_LABELS.put("title", "RETROSPECT");
		STOCK_LABELS.put("takeaway", "THE TAKEAWAY");
		STOCK_LABELS.put("tip", "TRY THIS");
		STOCK_LABELS.put("strong", "STRONG");
		STOCK_LABELS.put("weak", "WEAK");
		STOCK_LABELS.put("numbers", "NUMBERS");
		STOCK_LABELS.put("story", "WHAT HAPPENED");
		STOCK_LABELS.put("recent", "RECENT FIGHTS");

		STOCK_COLORS.put("accent", "F0B93A");
		STOCK_COLORS.put("strong", "8BD17C");
		STOCK_COLORS.put("weak", "E8765A");
		STOCK_COLORS.put("text", "E6D8BC");

		COLOR_NAMES.put("accent", "Headings");
		COLOR_NAMES.put("strong", "Strong");
		COLOR_NAMES.put("weak", "Weak");
		COLOR_NAMES.put("text", "Body text");
	}

	private Map<String, String> labels = new LinkedHashMap<>();
	private Map<String, String> colors = new LinkedHashMap<>();

	String label(String key)
	{
		String own = labels == null ? null : labels.get(key);
		return own != null && !own.trim().isEmpty() ? own : STOCK_LABELS.getOrDefault(key, key);
	}

	/** Blank text puts the stock heading back. */
	void setLabel(String key, String text)
	{
		if (!STOCK_LABELS.containsKey(key))
		{
			return;
		}
		String clean = text == null ? "" : text.replaceAll("[\\r\\n\\t]+", " ").trim();
		if (clean.length() > MAX_LABEL)
		{
			clean = clean.substring(0, MAX_LABEL).trim();
		}
		if (clean.isEmpty() || clean.equals(STOCK_LABELS.get(key)))
		{
			labels.remove(key);
		}
		else
		{
			labels.put(key, clean);
		}
	}

	Color color(String key)
	{
		String hex = colors == null ? null : colors.get(key);
		Color own = parse(hex);
		return own != null ? own : parse(STOCK_COLORS.getOrDefault(key, "FFFFFF"));
	}

	void setColor(String key, Color c)
	{
		if (!STOCK_COLORS.containsKey(key) || c == null)
		{
			return;
		}
		String hex = String.format("%06X", c.getRGB() & 0xFFFFFF);
		if (hex.equals(STOCK_COLORS.get(key)))
		{
			colors.remove(key);
		}
		else
		{
			colors.put(key, hex);
		}
	}

	boolean isStock()
	{
		return labels.isEmpty() && colors.isEmpty();
	}

	void reset()
	{
		labels.clear();
		colors.clear();
	}

	private static Color parse(String hex)
	{
		if (hex == null || !hex.matches("[0-9a-fA-F]{6}"))
		{
			return null;
		}
		return new Color(Integer.parseInt(hex, 16));
	}

	/** A missing or damaged file just means the stock look. */
	static PanelLook load(Filepath file, Gson gson)
	{
		PanelLook look = null;
		try
		{
			if (file.isFile())
			{
				try (Reader r = file.openBufferedReader())
				{
					look = gson.fromJson(r, PanelLook.class);
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			look = null;
		}
		if (look == null)
		{
			look = new PanelLook();
		}
		if (look.labels == null)
		{
			look.labels = new LinkedHashMap<>();
		}
		if (look.colors == null)
		{
			look.colors = new LinkedHashMap<>();
		}
		return look;
	}

	void save(Filepath file, Gson gson) throws IOException
	{
		file.getParent().createDirectories();
		file.write(gson.toJson(this));
	}
}

package com.retrospect;

import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.OutputStream;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BiConsumer;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Holds the rolling recording and saves clips and screenshots when a moment happens.
 * All the slow work (compressing and writing) happens off the game thread.
 *
 * Frames come from RuneLite's own renderer, the same source the built-in Screenshot plugin
 * uses, so only the game image can ever be captured: never the desktop or another window.
 */
@Singleton
class Recorder
{
	private static final Logger log = LoggerFactory.getLogger(Recorder.class);

	/**
	 * Set once from the plugin's own data directory. Plugins are handed a Filepath they cannot
	 * escape, so every write below is confined to it.
	 */
	private Filepath root;
	private Filepath clips;
	private Filepath shots;
	private Filepath folders;
	/** A run of back-to-back moments is saved as one clip, but never longer than this. */
	private static final long MAX_CLIP_MS = 45_000;
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("yyyy-MM-dd");
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH-mm-ss");

	private static final class Pending
	{
		long startMs;
		long endMs;
		String base;
		Filepath dir;
	}

	private final DrawManager drawManager;
	private final RetrospectConfig config;
	private final FrameBuffer buffer = new FrameBuffer();
	private final AtomicBoolean frameInFlight = new AtomicBoolean();

	private ScheduledExecutorService timer;
	private ExecutorService compressor;
	private ExecutorService writer;
	private ScheduledFuture<?> captureTask;
	private volatile boolean active;
	private Pending pending;
	/** Told about every saved file: (file, what kind of thing it is). */
	private volatile BiConsumer<Filepath, String> onSaved = (f, k) -> { };

	@Inject
	Recorder(DrawManager drawManager, RetrospectConfig config)
	{
		this.drawManager = drawManager;
		this.config = config;
	}

	void setOnSaved(BiConsumer<Filepath, String> onSaved)
	{
		this.onSaved = onSaved;
	}

	/** Called once on start up with the directory RuneLite gives the plugin. */
	synchronized void setRoot(Filepath root)
	{
		this.root = root;
		this.clips = root.join("clips");
		this.shots = root.join("screenshots");
		this.folders = root.join("folders");
	}

	Filepath root()
	{
		return root;
	}

	Filepath folders()
	{
		return folders;
	}

	boolean isRecording()
	{
		return active && config.recordClips() && captureTask != null;
	}

	double bufferMegabytes()
	{
		return buffer.getBytes() / 1048576.0;
	}

	synchronized void start()
	{
		timer = Executors.newSingleThreadScheduledExecutor(r -> daemon(r, "retrospect-timer"));
		compressor = Executors.newSingleThreadExecutor(r -> daemon(r, "retrospect-compress"));
		writer = Executors.newSingleThreadExecutor(r -> daemon(r, "retrospect-writer"));
		applyConfig();
	}

	synchronized void stop()
	{
		active = false;
		if (captureTask != null)
		{
			captureTask.cancel(false);
			captureTask = null;
		}
		for (ExecutorService e : new ExecutorService[]{timer, compressor, writer})
		{
			if (e != null)
			{
				e.shutdown();
			}
		}
		timer = null;
		compressor = null;
		writer = null;
		pending = null;
		buffer.clear();
		frameInFlight.set(false);
	}

	private static Thread daemon(Runnable r, String name)
	{
		Thread t = new Thread(r, name);
		t.setDaemon(true);
		t.setPriority(Thread.MIN_PRIORITY);
		return t;
	}

	/** Only record while logged in to the game. */
	void setActive(boolean active)
	{
		this.active = active;
		if (!active)
		{
			buffer.clear();
		}
	}

	/** Re-reads the settings and restarts the capture timer. */
	synchronized void applyConfig()
	{
		if (timer == null)
		{
			return;
		}
		buffer.setKeepMs((config.secondsBefore() + config.secondsAfter() + 3) * 1000L);
		buffer.setMaxBytes(config.maxMemoryMb() * 1024L * 1024L);
		if (captureTask != null)
		{
			captureTask.cancel(false);
			captureTask = null;
		}
		if (config.recordClips())
		{
			long period = Math.max(50, 1000 / Math.max(1, config.fps()));
			captureTask = timer.scheduleAtFixedRate(this::requestFrame, period, period, TimeUnit.MILLISECONDS);
		}
		else
		{
			buffer.clear();
		}
	}

	private void requestFrame()
	{
		try
		{
			if (!active || !frameInFlight.compareAndSet(false, true))
			{
				return; // logged out, or the last frame is still being handled: skip this one
			}
			final int height = config.clipSize().height;
			drawManager.requestNextFrameListener(image ->
			{
				final long now = System.currentTimeMillis();
				ExecutorService c = compressor;
				if (c == null)
				{
					frameInFlight.set(false);
					return;
				}
				try
				{
					c.execute(() ->
					{
						try
						{
							if (active && config.recordClips())
							{
								buffer.add(image, now, height, 0.72f);
							}
							// Recording may have been switched off while this frame was being compressed
							if (!active || !config.recordClips())
							{
								buffer.clear();
							}
						}
						catch (IOException | RuntimeException e)
						{
							log.debug("Could not buffer a frame", e);
						}
						finally
						{
							frameInFlight.set(false);
						}
					});
				}
				catch (RejectedExecutionException e)
				{
					frameInFlight.set(false); // the plugin was switched off between the request and the frame
				}
			});
		}
		catch (RuntimeException e)
		{
			frameInFlight.set(false);
			log.debug("Frame request failed", e);
		}
	}

	/**
	 * Something worth keeping just happened.
	 *
	 * @return the name the clip will be saved under (no extension), or null if no clip is being made
	 */
	String moment(String label, RetrospectConfig.Capture mode)
	{
		return moment(label, mode, null);
	}

	/**
	 * @param folder file this moment here instead of the dated clips and screenshots folders
	 *               (used in Serious mode to keep a boss's media together). Null for the usual place.
	 */
	String moment(String label, RetrospectConfig.Capture mode, Filepath folder)
	{
		if (mode == null || mode == RetrospectConfig.Capture.OFF || timer == null || root == null)
		{
			return null;
		}
		LocalDateTime when = LocalDateTime.now();
		String safe = ClipWriter.safeName(label);
		if (mode.screenshot())
		{
			final Filepath file = folder != null
				? folder.join(when.format(DAY) + "_" + when.format(TIME) + "_" + safe + ".png")
				: shots.join(when.format(DAY), when.format(TIME) + "_" + safe + ".png");
			drawManager.requestNextFrameListener(image -> screenshot(image, file));
		}
		if (!mode.clip() || !config.recordClips() || !active)
		{
			return null;
		}
		long now = System.currentTimeMillis();
		long after = config.secondsAfter() * 1000L;
		synchronized (this)
		{
			if (pending != null)
			{
				// A second moment while a clip is still rolling: stretch that clip instead of starting another
				pending.endMs = Math.min(Math.max(pending.endMs, now + after), pending.startMs + MAX_CLIP_MS);
				return pending.base;
			}
			pending = new Pending();
			pending.startMs = now - config.secondsBefore() * 1000L;
			pending.endMs = now + after;
			pending.dir = folder != null ? folder : clips.join(when.format(DAY));
			pending.base = (folder != null ? when.format(DAY) + "_" : "") + when.format(TIME) + "_" + safe;
			timer.schedule(this::finishPending, after + 400, TimeUnit.MILLISECONDS);
			return pending.base;
		}
	}

	private void finishPending()
	{
		final Pending p;
		synchronized (this)
		{
			p = pending;
			if (p == null || timer == null)
			{
				return;
			}
			long wait = p.endMs + 400 - System.currentTimeMillis();
			if (wait > 0)
			{
				timer.schedule(this::finishPending, wait, TimeUnit.MILLISECONDS);
				return;
			}
			pending = null;
		}
		final List<FrameBuffer.Frame> frames = buffer.snapshot(p.startMs, p.endMs);
		final int fps = Math.max(1, config.fps());
		final long capBytes = config.maxStorageGb() * 1024L * 1024L * 1024L;
		ExecutorService w = writer;
		if (w == null)
		{
			return;
		}
		try
		{
			w.execute(() -> saveClip(p, frames, fps, capBytes));
		}
		catch (RejectedExecutionException e)
		{
			log.debug("Clip {} dropped: the plugin was switched off", p.base);
		}
	}

	private void saveClip(Pending p, List<FrameBuffer.Frame> frames, int fps, long capBytes)
	{
		if (frames.size() < 2)
		{
			log.debug("No frames buffered for clip {}", p.base);
			return;
		}
		try
		{
			p.dir.createDirectories();
			Filepath clip = p.dir.join(p.base + ".avi");
			ClipWriter.writeAvi(frames, fps, clip);
			ClipWriter.enforceCap(clips, capBytes, clip);
			onSaved.accept(clip, "clip");
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not save clip {}", p.base, e);
		}
	}

	private void screenshot(Image image, Filepath file)
	{
		final BufferedImage copy = ImageUtil.bufferedImageFromImage(image);
		ExecutorService w = writer;
		if (w == null)
		{
			return;
		}
		try
		{
			w.execute(() ->
			{
				try
				{
					file.getParent().createDirectories();
					try (OutputStream os = file.openOutputStream())
					{
						ImageIO.write(copy, "png", os);
					}
					onSaved.accept(file, "screenshot");
				}
				catch (IOException | RuntimeException e)
				{
					log.warn("Could not save screenshot {}", file, e);
				}
			});
		}
		catch (RejectedExecutionException e)
		{
			log.debug("Screenshot dropped: the plugin was switched off");
		}
	}
}

package com.retrospect;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(RetrospectConfig.GROUP)
public interface RetrospectConfig extends Config
{
	String GROUP = "retrospect";

	/** What to save when a moment happens. */
	/**
	 * One switch over every automatic save, so a session like Soul Wars can be made
	 * quiet from the panel without touching seven separate settings. The "Clip that"
	 * button and hotkey are deliberate, so they keep working whatever this says.
	 */
	enum Saving
	{
		AS_SET("Clips + shots"),
		CLIPS("Clips only"),
		SHOTS("Shots only"),
		OFF("Off");

		private final String label;

		Saving(String label)
		{
			this.label = label;
		}

		String label()
		{
			return label;
		}

		Saving next()
		{
			return values()[(ordinal() + 1) % values().length];
		}

		/** What a moment that wanted {@code wanted} should actually save. */
		Capture apply(Capture wanted)
		{
			if (wanted == null || wanted == Capture.OFF || this == OFF)
			{
				return Capture.OFF;
			}
			switch (this)
			{
				case CLIPS:
					return Capture.CLIP;
				case SHOTS:
					return Capture.SCREENSHOT;
				default:
					return wanted;
			}
		}
	}

	enum Capture
	{
		OFF("Off"),
		SCREENSHOT("Screenshot"),
		CLIP("Clip"),
		BOTH("Clip + screenshot");

		private final String label;

		Capture(String label)
		{
			this.label = label;
		}

		boolean clip()
		{
			return this == CLIP || this == BOTH;
		}

		boolean screenshot()
		{
			return this == SCREENSHOT || this == BOTH;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** How much Retrospect keeps. */
	enum Mode
	{
		EVERYDAY("Everyday"),
		SERIOUS("Serious");

		private final String label;

		Mode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum ClipSize
	{
		P480("480p (smallest files)", 480),
		P720("720p", 720),
		P1080("1080p (heavy)", 1080);

		private final String label;
		final int height;

		ClipSize(String label, int height)
		{
			this.label = label;
			this.height = height;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(name = "Moments", description = "Which moments get saved, and how", position = 0)
	String moments = "moments";

	@ConfigSection(name = "Clips", description = "How clips are recorded and stored", position = 1)
	String clips = "clips";

	@ConfigSection(name = "Fight debrief", description = "The short write-up after each fight", position = 2)
	String debrief = "debrief";

	@ConfigItem(keyName = "saving", name = "Saving", description = "Master switch over every automatic save. Clips + shots uses each moment's own setting below; Off keeps nothing until you turn it back on. The Clip that button and hotkey always work.", position = -2)
	default Saving saving()
	{
		return Saving.AS_SET;
	}

	@ConfigItem(keyName = "mode", name = "Mode", description = "Everyday: catches your moments and shows the debrief, keeps nothing else. Serious: also files every fight's debrief and clips into that boss's folder.", position = -1)
	default Mode mode()
	{
		return Mode.EVERYDAY;
	}

	// ---------- Moments ----------

	@ConfigItem(keyName = "valuableDrop", name = "Valuable drop", description = "Loot worth at least the value below", section = moments, position = 0)
	default Capture valuableDrop()
	{
		return Capture.BOTH;
	}

	@Range(min = 1, max = 2_000_000_000)
	@ConfigItem(keyName = "dropValue", name = "Drop worth at least (gp)", description = "Total value of one drop that counts as valuable", section = moments, position = 1)
	default int dropValue()
	{
		return 1_000_000;
	}

	@ConfigItem(keyName = "personalBest", name = "New personal best", description = "The game says (new personal best) on a kill, lap or raid", section = moments, position = 2)
