	{
		return 10;
	}

	@Range(min = 1, max = 10)
	@Units(Units.SECONDS)
	@ConfigItem(keyName = "secondsAfter", name = "Seconds after the moment", description = "How long a clip keeps rolling afterwards", section = clips, position = 2)
	default int secondsAfter()
	{
		return 4;
