	/** The plugin's own directory, handed to us by RuneLite. Nothing is written outside it. */
	private Filepath dataDir;
	private Filepath lookFile;

	@Override
	protected void startUp() throws IOException
	{
		dataDir = getPluginDirectory();
		lookFile = dataDir.join("look.json");
		recorder.setRoot(dataDir);
		history = new FightHistory(dataDir.join("history.json"), gson);
		executor.execute(() ->
		{
			history.load();
			refreshRecent();
		});

		folders = new FightFolders(dataDir.join("folders.json"), gson);
		folders.load();
		look = PanelLook.load(lookFile, gson);
		panel = new RetrospectPanel(new PanelActions(), look);
		panel.setFolders(folders.all());
		panel.setSerious(serious());
		panel.setSaving(config.saving().label(), momentSettings());
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Retrospect")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		readSettings();
		recorder.setOnSaved(this::onSaved);
		recorder.start();
		recorder.setActive(client.getGameState() == GameState.LOGGED_IN);
		keyManager.registerKeyListener(hotkey);
		executor.schedule(this::refreshStatus, 3, java.util.concurrent.TimeUnit.SECONDS);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(hotkey);
		recorder.stop();
		clientToolbar.removeNavigation(navButton);
		tracker.forceEnd(client.getTickCount());
		focus = null;
		lastAnim.clear();
		playersHit.clear();
		lastMoment.clear();
		panel = null;
		navButton = null;
		fightFolder = null;
	}

	private boolean serious()
	{
		return config.mode() == RetrospectConfig.Mode.SERIOUS;
	}

	/** Everything the side panel can ask for. These run on the interface thread. */
	private final class PanelActions implements RetrospectPanel.Actions
	{
		@Override
