	@Test
	public void longTimelinesAreTrimmedToTheBiggestMoments()
	{
		EncounterTracker t = new EncounterTracker();
		attacks(t, 0, 5, 4, 20);
		for (int i = 0; i < 60; i++)
		{
			t.onHitTaken(20 + i * 5, 1 + i, "Vorkath", false, "14322", 99, 0L);
